-- Independent Dadyoom teaching supports, not claims about the contents of official books.
-- Idempotent: update only genuinely empty published lessons; add each origin/type once.
DO $dadyoom$
DECLARE
  r RECORD;
  target_id uuid;
  target_content text;
BEGIN
  FOR r IN SELECT * FROM jsonb_to_recordset('[{"n":1,"skill":"المشورة وبناء قرار معلل","passage":"يحتاج نص «أهمية المشورة» المنسوب إلى الأبشيهي إلى المصدر الأصلي للتحقق من نصه وشواهده. في موقف تدريبي مستقل اختار فريق تصميم مشروعه بعد الاستماع إلى اقتراحات ثلاثة أعضاء ومقارنة الكلفة والزمن والمخاطر، ثم أعلن سبب القرار. يظهر الفرق بين مجرد الاستماع والمشورة الموثقة.","prompt":"ما الذي جعل المشورة مفيدة في المثال؟","correct":"مقارنة المقترحات بمعايير واضحة","w1":"اختيار أول رأي فقط","w2":"تجاهل المخاطر","w3":"عدم إعلان السبب","practice":"استخرج من نص الأبشيهي المقرر دليلًا حقيقيًا على قيمة المشورة، ثم طبق المبدأ على قرار دراسي من إنشائك."},{"n":2,"skill":"التشبيه ووظيفته البلاغية","passage":"«العلمُ كالنورِ في الهداية» تشبيه مرسل مفصل: «العلم» مشبّه، و«النور» مشبّه به، والكاف أداة، و«الهداية» وجه الشبه. يمكن أن يخدم التشبيه توضيح المعنى وتقريبه، ولا يُفهم أن العلم مصدر ضوء مادي.","prompt":"ما المشبه به في المثال؟","correct":"النور","w1":"العلم","w2":"الهداية","w3":"الكاف","practice":"كوّن ثلاثة تشبيهات: مرسلًا مفصلًا ومؤكدًا ومجملًا، وحدد الأركان وفسر الأثر."},{"n":3,"skill":"التمييز بين الحقيقة والمجاز","passage":"«فتح التلميذ الباب» استعمال حقيقي في سياق باب محسوس، أما «فتح العلمُ أبوابَ الأمل» فتصوير مجازي، إذ نسب الفتح إلى العلم ونُقلت دلالة الأبواب إلى فرص الحياة. يعتمد التحليل على القرينة والسياق لا على كلمة منفردة.","prompt":"أي عبارة تتضمن تصويرًا مجازيًا؟","correct":"فتح العلم أبواب الأمل","w1":"فتح التلميذ الباب","w2":"دخل الطالب الفصل","w3":"قرأت المعلمة النص","practice":"اكتب خمس جمل حقيقية وخمس مجازية مع شرح القرينة وأثر التعبير في المعنى."},{"n":4,"skill":"فكرة الانتماء بلا نسبة قول مختلق","passage":"يُراجع نص «الوطنية» لمحمد عبده من مصدره قبل اقتباس أي عبارة أو تحديد دعوة الكاتب. تدريب مستقل: «نظّم الطلاب حملة لصيانة الكتب في مكتبة الحي مع التنسيق مع المسؤولين». تدل الوطنية هنا على خدمة عامة قابلة للتنفيذ ولا يمثل الموقف النص الأصلي.","prompt":"ما السلوك الذي دل على الخدمة العامة؟","correct":"صيانة الكتب بالتنسيق مع المسؤولين","w1":"إهمال المكتبة","w2":"نشر معلومات خاطئة","w3":"ترك العمل الجماعي","practice":"ارجع إلى النص المقرر واستخرج رأيًا صريحًا لصاحبه بشاهد موثق ثم ناقش تطبيقه الآن."},{"n":5,"skill":"تعزيز الحجة بموقف سردي","passage":"في حوار عن العمل الجماعي قال المتعلم: «توزيع المهام يساعد على إنجاز المشروع». ثم روى موقفًا تعطل فيه الفريق عندما لم يعرف أحد مسؤولية الفحص، وتحسن بعد تحديد الأدوار. يخدم السرد الحجة بإظهار سبب ونتيجة، لا بمجرد إطالة المقال.","prompt":"أي عنصر جعل السرد حجةً؟","correct":"إظهار أثر وضوح المسؤوليات على الإنجاز","w1":"ذكر الأسماء فقط","w2":"تكرار الرأي دون دليل","w3":"حذف النهاية","practice":"اكتب نصًا حجاجيًا من 120 كلمة يوظف قصة قصيرة مع تعليق يربطها بالأطروحة."},{"n":6,"skill":"الاستعارة المكنية والتصريحية","passage":"في «ابتسم الصباح» شُبّه الصباح بإنسان وحُذف المشبّه به وأُبقي فعل من لوازمه، فهي استعارة مكنية في التحليل المدرسي. وفي «رأيت أسدًا يقود الفريق» إذا قصدنا رجلًا شجاعًا فهي استعارة تصريحية، مع قرينة تمنع المعنى الحيواني.","prompt":"ما نوع الاستعارة في «ابتسم الصباح»؟","correct":"استعارة مكنية","w1":"تشبيه تام الأركان","w2":"طباق","w3":"جناس","practice":"أنشئ مثالين لكل نوع من الاستعارة مع تحديد القرينة والمشبه والمشبه به المقصود."},{"n":7,"skill":"قراءة الرسائل التاريخية بحذر","passage":"يتطلب درس «رسالة الأمين إلى المأمون» في رواية الطبري الاطلاع على النص المقرر ومصدره التاريخي قبل تقرير مضمون الرسالة أو نسبة اقتباس. نموذج أصلي: «كتب مدير مشروع إلى زميله يطلب توضيح سبب التأخير ويقترح موعدًا للحل». يصلح لفهم مقصد الرسائل لكنه ليس نصًا تاريخيًا.","prompt":"ما الهدف الظاهر للرسالة المستقلة؟","correct":"طلب التوضيح واقتراح حل","w1":"إخفاء المشكلة","w2":"إعلان الانسحاب بلا سبب","w3":"تجاهل الزميل","practice":"استخرج غرض الرسالة التاريخية وشاهدًا أصليًا بعد التوثيق، ثم اكتب رسالة رسمية ذات غرض واضح."},{"n":8,"skill":"المجاز المرسل وعلاقته","passage":"في «شربتُ كأسًا» قد يُراد شرب ما في الكأس، فتكون العلاقة المحلية لأن الوعاء محل للمحتوى، إن قامت القرينة على ذلك. وفي «قرأتُ لطه حسين» يمكن أن يُراد قراءة مؤلفاته في سياق مجازي. يجب شرح العلاقة والقرينة بدقة لا تصنيف كل لفظ وحده.","prompt":"ما الذي يُراد غالبًا بـ«شربت كأسًا»؟","correct":"ما في الكأس من شراب","w1":"الكأس الزجاجية نفسها","w2":"الطاولة","w3":"القلم","practice":"أنشئ أربعة أمثلة للمجاز المرسل، واذكر العلاقة والقرينة وفرقها عن الاستعارة."},{"n":9,"skill":"التوثيق عند قراءة مشاهد السفر","passage":"لا يمكن نسبة أحكام عن أهل باريس إلى رفاعة الطهطاوي اعتمادًا على عنوان «في الكلام على أهل باريس» فقط. في نص مستقل وصف مسافر أنظمة النقل التي شاهدها، وميّز بين مشاهدته الفردية وأحكام تحتاج عينات أوسع. مهارة القراءة هنا تمييز الوصف والتعميم.","prompt":"ما الذي ينبغي تجنبه في تقرير المسافر؟","correct":"تعميم المشاهدة الفردية بلا دليل","w1":"تسجيل الملاحظات","w2":"ذكر المصادر","w3":"التمييز بين الرأي والواقع","practice":"اقرأ نص الطهطاوي الأصلي واستخرج وصفًا موثقًا ثم ناقش حدود تعميمه في السياق التاريخي."},{"n":10,"skill":"الوصف الداعم للحجاج","passage":"أطروحة تدريبية: «تحتاج المدارس إلى زوايا قراءة هادئة». يدعمها وصف غرفة مزدحمة تنقطع فيها القراءة من الضوضاء، ثم وصف تنظيم بسيط يخفف الإزعاج. يقنع الوصف إذا ارتبط بوضوح السبب والمقارنة، لا بالزينة اللفظية وحدها.","prompt":"ما وظيفة وصف الضوضاء في الحجة؟","correct":"توضيح المشكلة التي تعالجها الأطروحة","w1":"تكرار العنوان","w2":"إلغاء السبب","w3":"صرف القارئ عن الموضوع","practice":"اكتب نصًا حجاجيًا يستعين بوصف مكان حقيقي أو متخيل مع رأي ومثال ونتيجة دون ادعاء بيانات."},{"n":11,"skill":"الكناية وعلاقتها بالمعنى","passage":"«فلانٌ نظيفُ اليد» كناية شائعة عن الأمانة أو النزاهة حين يدل السياق على ذلك، ولا يُقصد بها مجرد غسل اليدين. للكناية معنى ملازم يُفهم مع جواز إرادة المعنى الأصلي في كثير من التطبيقات البلاغية.","prompt":"ما المعنى المقصود من «نظيف اليد» في سياق الأمانة؟","correct":"النزاهة","w1":"السرعة","w2":"الطول","w3":"الحزن","practice":"أنشئ خمس كنايات واضحة المعنى وفسر الصفة أو الموصوف المقصود مع قرينة كل مثال."},{"n":12,"skill":"الجناس والسجع في النثر","passage":"الجناس تقارب بين لفظين في المبنى واختلاف في المعنى، ويتطلب فحص التطابق أو الاختلاف بين الحروف والحركات. السجع توافق أواخر الفواصل في النثر مثل «العلمُ نور، والجهلُ غرور» في مثال تدريبي إيقاعي، ويجب ألا يطغى الصوت على المعنى.","prompt":"أي ظاهرة تتعلق بتوافق أواخر فواصل النثر؟","correct":"السجع","w1":"الطباق","w2":"المفعول به","w3":"التمييز","practice":"اكتب جملتين بسجع معتدل ثم ابحث عن مثال صحيح للجناس من نص موثوق واشرح اختلاف المعنى."},{"n":13,"skill":"الطباق والمقابلة","passage":"«النور والظلام» طباق بين ضدين، أما المقابلة فتعرض معنيين أو أكثر ثم ما يقابلها بترتيب، مثل بناء أصلي عن «الصدق يطمئن القلوب والكذب يزرع الشك» مع ضرورة تحديد المقابلة بدقة في النص. لا تجعل كل كلمتين مختلفتين تضادًا.","prompt":"أي زوج لفظي يمثل طباقًا؟","correct":"النور والظلام","w1":"النور والضياء","w2":"الصدق والأمانة","w3":"قلم وكتاب","practice":"اكتب ثلاثة أمثلة للطباق وأحدها للنفي والإثبات ثم صغ مقابلة بين معنيين واشرح أثرها."},{"n":901,"skill":"الطبع والتطبع من نص موثق","passage":"يحتاج نص «الطبع والتطبع» لابن عبد ربه إلى قراءة حقيقية قبل تلخيص موقف الكاتب. في قصة مستقلة كان متدرب سريع الانفعال، فتدرب على الإنصات قبل الرد وسجل أثر ذلك على نقاشات الفريق. يبين المثال إمكان تهذيب السلوك، ولا يمثل أحداث النص المدرسي.","prompt":"ما السلوك الذي تعلمه المتدرب؟","correct":"الإنصات قبل الرد","w1":"الصياح","w2":"المقاطعة","w3":"تجاهل الفريق","practice":"وثق فكرة من نص ابن عبد ربه ثم ناقشها بمثال واقعي أو متخيل يحدد العادة وطريقة تطويرها."},{"n":902,"skill":"الفردية والتعاون بمنطق السبب والنتيجة","passage":"لا يُنسب موقف من تأليف ضاديوم إلى نص «الفردية سوس ينخر المجتمع» لخليل هنداوي. في مثال مستقل احتفظ عضو فريق بالمعلومات اللازمة للعمل لنفسه، فتعطل المشروع، ثم شاركها فاستأنف الآخرون العمل. يظهر أثر الأنانية على المصلحة المشتركة.","prompt":"ما سبب تعطل المشروع أولًا؟","correct":"حجب المعلومات عن الفريق","w1":"التعاون المتبادل","w2":"توضيح الأدوار","w3":"مراجعة النتائج","practice":"استخرج حجة موثقة من النص المقرر، ثم أنشئ مشهدًا يوضح أثر العمل الفردي غير المنظم."}]'::jsonb) AS x(
    n integer,skill text,passage text,prompt text,correct text,w1 text,w2 text,w3 text,practice text
  ) LOOP
    SELECT l.id,l.content INTO STRICT target_id,target_content
    FROM public.lessons l
    JOIN public.units u ON u.id=l.unit_id
    JOIN public.grades g ON g.id=u.grade_id AND g.grade_number=11
    JOIN public.curricula cu ON cu.id=g.curriculum_id AND cu.academic_year='2026-2027' AND cu.id='31c82c79-72de-4e4b-a5dc-6f9e598b3533'
    JOIN public.countries c ON c.id=cu.country_id AND c.code='BH'
    WHERE u.title='عرب 202 — الأدب والحياة' AND u.semester=2 AND l.sort_order=r.n AND l.status='published'
    FOR UPDATE OF l;
    IF char_length(coalesce(target_content,''))<350 THEN
      UPDATE public.lessons SET
        content='ضاديوم — إثراء مستقل أصلي للصف الثامن، الفصل الثاني. لا يمثل النص الوزاري الأصلي ولا يثبت مطابقة العنوان للمصدر.'||E'\n\n'||
          'المهارة: '||r.skill||E'\n\n'||
          'النموذج التعليمي والشرح: '||r.passage||E'\n\n'||
          'أهداف التعلم: يحدد المتعلم شاهدًا صحيحًا ويشرح دلالته، ويميّز بين الفكرة والدليل، ثم ينتج كتابة مناسبة للمهارة.'||E'\n\n'||
          'سؤال الفهم: '||r.prompt||E'\n\n'||
          'التطبيق الكتابي: '||r.practice||E'\n\n'||
          'التمايز: المبتدئ يحصل على كلمات مفتاحية وبداية جملة؛ المتوسط يجيب بدليل مستقل؛ المتقدم يقارن بين صياغتين ويبرر تحسيناته.'||E'\n\n'||
          'مراجعة المعلم: تحقق من صحة الاستدلال والإملاء وعلامات الترقيم والترابط. لا تُمنح درجة جودة تلقائية لمجرد تسليم المهمة.'||E'\n\n'||
          'تنبيه المصدر: راجع العنوان المستورد والكتاب الرسمي قبل وصف هذا التدريب بأنه مطابق للمنهج.'||E'\n\n'||'المدخل السابق المحفوظ: '||coalesce(target_content,''),
        updated_at=now()
      WHERE id=target_id;
    END IF;
    IF EXISTS (SELECT 1 FROM public.lessons WHERE id=target_id AND content LIKE 'ضاديوم — إثراء مستقل أصلي للصف الثامن%') THEN
      INSERT INTO public.lesson_activities (lesson_id,title,activity_type,section,prompt,content,answer,activity_order,points,is_required,is_published)
      SELECT target_id,'فهم النص الإثرائي','multiple_choice','assessment',r.prompt,
        jsonb_build_object('origin','DADYOOM_BH_UNIFIED_G11_T2_ARAB202_ORIGINAL_20261008','notOfficialBook',true,'ocrReview','pending','options',CASE (r.n % 4) WHEN 0 THEN jsonb_build_array(r.correct,r.w1,r.w2,r.w3) WHEN 1 THEN jsonb_build_array(r.w1,r.correct,r.w2,r.w3) WHEN 2 THEN jsonb_build_array(r.w1,r.w2,r.correct,r.w3) ELSE jsonb_build_array(r.w1,r.w2,r.w3,r.correct) END),
        jsonb_build_object('correct',r.correct),
        coalesce((SELECT max(activity_order) FROM public.lesson_activities WHERE lesson_id=target_id),0)+1,5,true,true
      WHERE NOT EXISTS (SELECT 1 FROM public.lesson_activities WHERE lesson_id=target_id AND activity_type='multiple_choice' AND content->>'origin'='DADYOOM_BH_UNIFIED_G11_T2_ARAB202_ORIGINAL_20261008');
      INSERT INTO public.lesson_activities (lesson_id,title,activity_type,section,prompt,content,answer,activity_order,points,is_required,is_published)
      SELECT target_id,'كتابة تطبيقية بمراجعة المعلم','writing','practice',r.practice,
        jsonb_build_object('origin','DADYOOM_BH_UNIFIED_G11_T2_ARAB202_ORIGINAL_20261008','notOfficialBook',true,'humanReviewRequired',true,'text',r.practice,'skillQualityAutoVerified',false),
        jsonb_build_object('grading_mode','completion_only_reference','model_answer','لا تكفي المطابقة النصية؛ يصحح المعلم ملاءمة الأفكار والدليل والترابط.'),
        coalesce((SELECT max(activity_order) FROM public.lesson_activities WHERE lesson_id=target_id),0)+1,5,true,true
      WHERE NOT EXISTS (SELECT 1 FROM public.lesson_activities WHERE lesson_id=target_id AND activity_type='writing' AND content->>'origin'='DADYOOM_BH_UNIFIED_G11_T2_ARAB202_ORIGINAL_20261008');
    END IF;
  END LOOP;
END
$dadyoom$;